def promotion_gate(current, candidate, min_gain=0.01, max_segment_drop=0.02):
    """Decide whether a retrained model replaces the live one."""
    if candidate["overall"] - current["overall"] < min_gain:
        return False, "not enough overall gain"
    for seg, score in candidate["segments"].items():
        if current["segments"][seg] - score > max_segment_drop:
            return False, f"regression on segment {seg}"
    return True, "promote"

current = {"overall": 0.86, "segments": {"car": 0.88, "motorcycle": 0.81}}
