def check_claim(claim: dict) -> list[str]:
    """Return a list of data-quality problems (empty list = OK)."""
    problems = []
    if not claim.get("vehicle_reg"):
        problems.append("missing vehicle_reg")
    if claim.get("estimated_cost", 0) < 0:
        problems.append("negative estimated_cost")
    if problems:
        log.warning("dq_fail", extra={"claim_id": claim["id"], "problems": problems})
    return problems

from datetime import date, datetime
import httpx
from pydantic import BaseModel, field_validator

class DocumentNotFound(Exception): ...

class Document(BaseModel):
    id: str
    title: str
    created: date

    @field_validator("created", mode="before")
    @classmethod
    def parse_uk_date(cls, v):               # API sends "14/03/2026"
        return datetime.strptime(v, "%d/%m/%Y").date() if isinstance(v, str) else v

def list_documents(client: httpx.Client, claim_id: str) -> list[Document]:
    docs, cursor = [], None
    while True:
        params = {"claim_id": claim_id, **({"cursor": cursor} if cursor else {})}
        body = client.get("/documents", params=params).json()
        if "error" in body:                  # API returns 200 with an error field
            raise DocumentNotFound(body["error"])
        docs += [Document.model_validate(d) for d in body["items"]]
        cursor = body.get("next_cursor")
        if not cursor:
            return docs

import time
from collections import defaultdict

def fetch_all(client, max_retries=3):
    """Yield orders from every page, retrying on HTTP 429."""
    page = 1
    while page:
        for attempt in range(max_retries):
            status, body = client.get_orders(page)
            if status != 429:
                break
            time.sleep(2 ** attempt)            # back off: 1s, 2s, 4s
        else:
            raise RuntimeError(f"page {page} still rate limited")
        yield from body["orders"]
        page = body.get("next_page")

def revenue_by_customer(client):
    totals = defaultdict(float)
    for o in fetch_all(client):
        totals[o["customer_id"]] += o["amount"]
    return dict(totals)

