class FakeClient:
    def __init__(self): self.calls = 0
    def get_orders(self, page):
        self.calls += 1
        if self.calls == 1: return 429, {}
        pages = {1: {"orders": [{"customer_id": "a", "amount": 10.0}], "next_page": 2},
                 2: {"orders": [{"customer_id": "a", "amount": 5.0}], "next_page": None}}
        return 200, pages[page]

def test_retries_and_pages(monkeypatch):
    monkeypatch.setattr(time, "sleep", lambda s: None)
    assert revenue_by_customer(FakeClient()) == {"a": 15.0}

import anthropic

client = anthropic.Anthropic()          # reads ANTHROPIC_API_KEY
MODEL = "MODEL"                         # placeholder: a small, cheap model

GRADE_TOOL = {
    "name": "record_grade",
    "description": "Record whether the passages answer the question.",
    "input_schema": {
        "type": "object",
        "properties": {
            "relevant": {"type": "boolean"},
            "reason": {"type": "string"},
        },
        "required": ["relevant", "reason"],
    },
}

def grade_chunks(question: str, chunks: list[dict]) -> bool:
    passages = "\n---\n".join(c["content"] for c in chunks)
    resp = client.messages.create(
        model=MODEL,
        max_tokens=300,
        tools=[GRADE_TOOL],
        tool_choice={"type": "tool", "name": "record_grade"},   # force structured output
        messages=[{"role": "user",
                   "content": f"Question: {question}\n\nPassages:\n{passages}"}],
    )
    for block in resp.content:
        if block.type == "tool_use":
            return bool(block.input["relevant"])
    return False
